-- Generated by build_world_batch.py. See its docstring and each
-- region's notes; style.json holds every claim's sources.

begin;

insert into public.wine_regions
  (region_code, name, aliases, country_code, latitude, longitude, radius_km,
   summary, red_body, red_acidity, red_tannin, pairing, label_note,
   source_url, publication_status)
values
  ('wr_0080', 'Rheingau', '{}'::text[], 'DE', 50.067, 8.093, 17,
   'A small region on the right bank of the Rhine in Hesse, mostly in the Rheingau-Taunus district. Riesling covers about three quarters of the vineyards and Spätburgunder most of the rest.',
   null, null, null, null, 'Labels show Qualitätswein or Prädikatswein. The Prädikat levels are Kabinett, Spätlese, Auslese, Beerenauslese, Trockenbeerenauslese and Eiswein, and every wine must pass an official quality test.',
   'https://en.wikipedia.org/wiki/Rheingau_(wine_region)', 'published'),
  ('wr_0081', 'Pfalz', '{"Palatinate","Rheinpfalz"}'::text[], 'DE', 49.358, 8.197, 24,
   'Germany''s second largest wine region, a long strip below the Haardt hills at the edge of the Palatinate Forest. It is one of the sunniest and driest German regions, with a climate compared to Alsace.',
   null, null, null, null, 'Labels show Qualitätswein or Prädikatswein. The Prädikat levels are Kabinett, Spätlese, Auslese, Beerenauslese, Trockenbeerenauslese and Eiswein, and every wine must pass an official quality test.',
   'https://en.wikipedia.org/wiki/Pfalz_(wine_region)', 'published'),
  ('wr_0082', 'Rheinhessen', '{}'::text[], 'DE', 49.799, 8.134, 21,
   'Germany''s largest wine region, rolling hill country inside the bend of the Rhine between Bingen, Mainz and Worms. It makes mostly white wine from Riesling, Müller-Thurgau and Silvaner, with Dornfelder the main red.',
   null, null, null, null, 'Labels show Qualitätswein or Prädikatswein. The Prädikat levels are Kabinett, Spätlese, Auslese, Beerenauslese, Trockenbeerenauslese and Eiswein, and every wine must pass an official quality test.',
   'https://en.wikipedia.org/wiki/Rheinhessen_(wine_region)', 'published'),
  ('wr_0083', 'Nahe', '{}'::text[], 'DE', 49.802, 7.696, 16,
   'A small region along the river Nahe from near Kirn down to Bingen, with an unusually wide range of soils, many of volcanic origin. Most of the wine is white and Riesling leads.',
   null, null, null, null, 'Labels show Qualitätswein or Prädikatswein. The Prädikat levels are Kabinett, Spätlese, Auslese, Beerenauslese, Trockenbeerenauslese and Eiswein, and every wine must pass an official quality test.',
   'https://en.wikipedia.org/wiki/Nahe_(wine_region)', 'published'),
  ('wr_0084', 'Franken', '{}'::text[], 'DE', 49.831, 9.761, 35,
   'The wine region of Bavaria, following the bends of the Main around Würzburg. Mostly dry white wines from Silvaner and Müller-Thurgau, many bottled in the flat, round Bocksbeutel.',
   null, null, null, null, 'Labels show Qualitätswein or Prädikatswein. The Prädikat levels are Kabinett, Spätlese, Auslese, Beerenauslese, Trockenbeerenauslese and Eiswein, and every wine must pass an official quality test. In Franken, Spätlese and the higher Prädikate may only be used together with a single vineyard (Einzellage) or Gewann name. The official term Erstes Gewächs is reserved for separately delimited sites with lower yield limits.',
   'https://en.wikipedia.org/wiki/Franconia_(wine_region)', 'published'),
  ('wr_0085', 'Baden', '{}'::text[], 'DE', 49.572, 9.661, 43,
   'Germany''s southernmost region, warm and sunny, stretching about 400 km along the Rhine from Lake Constance to near Heidelberg. The Pinot family dominates, led by Spätburgunder.',
   null, null, null, null, 'Labels show Qualitätswein or Prädikatswein. The Prädikat levels are Kabinett, Spätlese, Auslese, Beerenauslese, Trockenbeerenauslese and Eiswein, and every wine must pass an official quality test. The Bocksbeutel bottle is traditional for wines from the Taubertal and Schüpfergrund, and from Neuweier, Steinbach, Umweg and Varnhalt in Baden-Baden.',
   'https://en.wikipedia.org/wiki/Baden_(wine_region)', 'published'),
  ('wr_0086', 'Ahr', '{}'::text[], 'DE', 50.532, 7.086, 7,
   'A small valley region on a tributary of the Rhine and one of the most northerly wine regions in Europe, known for red wine. Spätburgunder is the main grape, grown on terraces of slate.',
   null, null, null, null, 'Labels show Qualitätswein or Prädikatswein. The Prädikat levels are Kabinett, Spätlese, Auslese, Beerenauslese, Trockenbeerenauslese and Eiswein, and every wine must pass an official quality test.',
   'https://en.wikipedia.org/wiki/Ahr_(wine_region)', 'published'),
  ('wr_0087', 'Valpolicella', '{}'::text[], 'IT', 45.519, 11.013, 15,
   'A Veneto red wine zone in the hills north of Verona, with vineyards on largely calcareous soils. Styles run from fresh, light reds with high acidity to Amarone, made from partly dried grapes.',
   2, 4, 2, 'Simple Valpolicella suits burgers and roast or grilled chicken.', 'Classico: only from the historic zone of Negrar, Marano, Fumane, Sant''Ambrogio and San Pietro in Cariano. Valpantena: from that valley. Superiore: at least one year of ageing from 1 January after the harvest. Amarone needs at least two years, and four for Riserva.',
   'https://winefolly.com/wine-styles/valpolicella', 'published'),
  ('wr_0088', 'Soave', '{}'::text[], 'IT', 45.476, 11.209, 9,
   'Hills east of Verona where volcanic basalt and limestone soils meet. Garganega gives dry, crisp whites with good acidity, often with an almond note on the finish.',
   null, null, null, 'Soave suits fish, from lighter fish dishes to tuna sashimi.', 'Classico: only from the historic zone in part of Soave and Monteforte d''Alpone, recognised in 1931. Colli Scaligeri is a hill sub zone. Soave Superiore and Recioto di Soave are separate DOCGs.',
   'https://italianwinecentral.com/profile-soave/', 'published'),
  ('wr_0089', 'Prosecco', '{}'::text[], 'IT', 45.888, 12.425, 82,
   'Prosecco DOC spans nine provinces across Veneto and Friuli Venezia Giulia in northeast Italy. Made mainly from Glera, with the second fermentation in tank, the wines are fruity, with green apple and pear notes.',
   null, null, null, 'Prosecco suits Italian cured meats and spicy noodle dishes.', 'Made as Prosecco, Prosecco spumante, spumante rosé and frizzante. "Treviso" or "Trieste" may appear when all grapes come from, and the wine is made and bottled in, that province.',
   'https://www.prosecco.wine/en', 'published'),
  ('wr_0090', 'Alto Adige', '{"Südtirol","dell''Alto Adige"}'::text[], 'IT', 46.509, 11.443, 26,
   'Alpine valleys in Italy''s far north, with vineyards from warm low sites around Bolzano to cool high slopes. About two thirds of the wine is white, beside light Schiava and darker, firmer Lagrein reds.',
   null, null, null, null, 'The German "Südtirol" or "Südtiroler" may be used. Riserva needs at least two years of ageing from 1 October of the harvest year. Six sub zones may be named on the label.',
   'https://winefolly.com/deep-dive/alto-adige-wine-region/', 'published'),
  ('wr_0091', 'Friuli', '{"Friuli Venezia Giulia","Furlanija"}'::text[], 'IT', 45.957, 13.033, 38,
   'Hills and stony plains of Friuli Venezia Giulia, sheltered by the Alps to the north and tempered by the Adriatic. Most of its types are named after one grape, whites such as Friulano and Ribolla Gialla beside reds such as Merlot.',
   null, null, null, 'Friulano suits prosciutto.', 'Varietal wines need at least 85 percent of the named grape. No type may use Riserva. The Slovenian names Furlanija and Furlanija Julijska krajina may be used.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_E-N/Friuli_o_Friuli_Venezia_Giulia.pdf', 'published'),
  ('wr_0092', 'Etna', '{}'::text[], 'IT', 37.694, 15.047, 19,
   'Vineyards on the slopes of Mount Etna in Sicily, on volcanic soils. Reds from Nerello Mascalese are pale in colour and light in body, yet tannic.',
   2, null, 4, null, 'Rosso Riserva needs at least four years of ageing, twelve months in wood. Bianco Superiore comes only from Milo. Spumante is bottle fermented with at least 18 months on the lees. A listed contrada may follow the name.',
   'https://vinepair.com/wine-101/nerello-mascalese/', 'published'),
  ('wr_0093', 'Franciacorta', '{}'::text[], 'IT', 45.603, 10.049, 9,
   'Morainic hills just south of Lake Iseo, near Brescia in Lombardy. The sparkling wines get their second fermentation in the bottle and age at least 18 months on the lees.',
   null, null, null, 'Franciacorta suits cheese, including soft cheeses.', 'Minimum time on the lees: 18 months, 24 for Satèn and Rosé, 30 for Millesimato, 60 for Riserva, which must also show the vintage.',
   'https://franciacorta.wine/en/wine/geology-climate/', 'published'),
  ('wr_0094', 'Taurasi', '{}'::text[], 'IT', 40.995, 14.953, 9,
   'Hills of Irpinia in the province of Avellino, inland Campania, with volcanic soils in places. Taurasi is made mostly from Aglianico, a tannic red with high acidity that is built for long ageing.',
   5, 4, 4, null, 'At least three years of ageing, one in wood, before release. Riserva needs four years, eighteen months in wood.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_O-Z/Taurasi.pdf', 'published'),
  ('wr_0095', 'Priorat', '{"Priorato","DOQ Priorat","DOCa Priorat"}'::text[], 'ES', 41.222, 0.806, 8,
   'Steep Catalan hills where Garnacha and Cariñena grow on llicorella, a dark slate soil. The region is known above all for full-bodied red wines.',
   4, null, null, null, 'Wines from one village may say ''vino de vila de'' and the village name. Single sites may be labelled Paraje, Viña Clasificada or Gran Viña Clasificada, and estate wines ''vino de finca''.',
   'https://www.doqpriorat.org/en/varietals/', 'published'),
  ('wr_0096', 'Rías Baixas', '{"Rias Baixas","DO Rías Baixas"}'::text[], 'ES', 42.733, -8.511, 23,
   'Galicia''s Atlantic coast, where Albariño makes almost all the wine. The whites are light, fresh and high in acidity, often with a saline edge, from vines on granite.',
   null, null, null, 'Seafood.', '''Rías Baixas Albariño'' is 100% Albariño. Oak aged whites are sold as ''Rías Baixas barrica''. Subzone names may be used for wines of the subzone.',
   'https://doriasbaixas.com/en/our-wines/', 'published'),
  ('wr_0097', 'Jerez-Xérès-Sherry', '{"Sherry","Jerez","Xérès"}'::text[], 'ES', 36.701, -6.174, 29,
   'Fortified wines from the Cádiz coast, made mainly from Palomino grown on white albariza soil and aged in soleras, either under a veil of flor yeast or exposed to air.',
   null, null, null, 'Fino and Manzanilla with fish and seafood.', 'Dry styles are Fino, Amontillado, Palo Cortado and Oloroso; sweet ones Pedro Ximénez and Moscatel; blends Pale Dry, Pale Cream, Medium and Cream. Age statements: 12 and 15 years, VOS (20) and VORS (30).',
   'https://www.sherry.wine/sherry-wine/production/viticulture', 'published'),
  ('wr_0098', 'Penedès', '{"Penedés","DO Penedès"}'::text[], 'ES', 41.377, 1.681, 22,
   'Catalan region south west of Barcelona, best known for white and sparkling wines from Xarel·lo, Macabeo and Parellada. Most of Spain''s Cava is made here.',
   null, null, null, 'Whites and sparkling wines with fish and seafood.', 'Clàssic Penedès is the DO''s own traditional method sparkling wine, from organic grapes with at least 15 months on the lees in bottle. ''Vino de Mas'' and ''Gran Vino de Mas'' mark single estate wines.',
   'https://dopenedes.cat/en/dopenedes/', 'published'),
  ('wr_0099', 'Rueda', '{"DO Rueda"}'::text[], 'ES', 41.262, -4.944, 30,
   'High, flat plateau in Castilla y León where Verdejo makes most of the wine: crisp, herbal whites from deep, well drained soils and a harsh climate.',
   null, null, null, 'Seafood.', '''Gran Vino de Rueda'' and ''Fermentado en barrica'' are regulated label terms. Dorado and Pálido are the traditional fortified wines.',
   'https://www.decanter.com/wine/wine-regions/rueda-wines/the-verdejo-grape-rueda-373802/', 'published'),
  ('wr_0100', 'Bierzo', '{"El Bierzo","DO Bierzo"}'::text[], 'ES', 42.571, -6.651, 28,
   'In the west of León, Bierzo is known for fragrant, medium-bodied reds from Mencía, often from old vines on slate soils. Godello is the leading white grape.',
   3, 4, 3, 'Hearty stews.', 'Vino de Villa, Vino de Paraje, Viña Clasificada and Gran Viña Clasificada mark wines from one village, one site or one classified vineyard, at lower yields. Crianza, Reserva and Gran Reserva are also used.',
   'https://www.guildsomm.com/public_content/features/articles/b/miquel_hudin/posts/godello-mencia-northwest-spain', 'published'),
  ('wr_0101', 'Toro', '{"DO Toro"}'::text[], 'ES', 41.426, -5.463, 15,
   'On the Duero in Zamora, a hot, dry continental climate gives red wines made mainly from Tinta de Toro, the local form of Tempranillo. Garnacha plays a smaller part.',
   null, null, null, null, 'Barrel aged reds may carry Roble, Crianza, Reserva or Gran Reserva. A red named after its grape needs at least 85% of it.',
   'https://dotoro.com/en/grapes/', 'published'),
  ('wr_0102', 'Vinho Verde', '{"Vinhos Verdes","Região Demarcada dos Vinhos Verdes"}'::text[], 'PT', 41.461, -8.263, 52,
   'Portugal''s rainy, Atlantic north west, mostly on granite. Its whites are light and fresh, with high acidity and fruity or floral aromas, from blends or single grapes such as Alvarinho and Loureiro.',
   null, null, null, 'Fish', 'A wine labelled Alvarinho alone must be made only from Alvarinho; named beside other grapes it must be at least 30% of the blend. Origem do Alvarinho is reserved for Monção e Melgaço.',
   'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=OJ:C_202403412', 'published'),
  ('wr_0103', 'Dão', '{"Dao","Região Demarcada do Dão"}'::text[], 'PT', 40.506, -7.882, 35,
   'A granite plateau ringed by mountains in north central Portugal. Its reds, led by Touriga Nacional, are fresh rather than heavy and age well; Encruzado is the key white.',
   3, 4, 3, null, 'Dão Nobre must show the vintage and age at least 36 months for reds and 12 for whites; reds need at least 15% Touriga Nacional, whites at least 15% Encruzado.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/16844', 'published'),
  ('wr_0104', 'Bairrada', '{}'::text[], 'PT', 40.453, -8.510, 19,
   'Flat land near the Atlantic between the Vouga and Mondego rivers, largely on clay and limestone. Baga gives tannic, high acid reds that soften with age, and the region is known for sparkling wine.',
   null, 5, 4, null, 'Clássico on the label means traditional grapes only, lower yields and long ageing: reds at least 30 months with 12 in bottle, whites 12 months with 6 in bottle.',
   'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=uriserv%3AOJ.C_.2023.224.01.0043.01.ENG', 'published'),
  ('wr_0105', 'Madeira', '{"Vinho da Madeira","Madeira Wine","Madère"}'::text[], 'PT', 32.760, -16.991, 16,
   'Fortified wine from steep volcanic terraces on Madeira and Porto Santo, with a high acidity found in every style. Styles run from dry Sercial and medium dry Verdelho to Boal and sweet Malvasia.',
   null, null, null, null, 'Age statements of 5, 10, 15, 20, 30 and over 40 years are allowed. Colheita and Frasqueira, also called Garrafeira, must show the harvest year.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/10001', 'published'),
  ('wr_0106', 'Setúbal', '{"Setubal","Moscatel de Setúbal"}'::text[], 'PT', 38.630, -8.801, 20,
   'South of Lisbon, the Setúbal DO is reserved for fortified Moscatel. Moscatel de Setúbal, from Muscat of Alexandria, is sweet and aromatic; Moscatel Roxo, from the grape of that name, is rarer.',
   null, null, null, null, 'Every Setúbal wine needs at least 67% Moscatel de Setúbal (white) or Moscatel Roxo (red); to carry either name on the label it needs 85%.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/16888', 'published'),
  ('wr_0107', 'Alsace', '{"Vin d''Alsace"}'::text[], 'FR', 48.203, 7.323, 21,
   'Alsace, on the foothills of the Vosges, makes mostly dry white wines, usually sold under the name of the grape. It also makes red and rosé from Pinot Noir and the sparkling Crémant d''Alsace.',
   null, null, null, null, 'A grape name on an Alsace label means the wine comes only from that grape, two grape names may not share a label, and the still wines go in the tall Vin du Rhin flute bottle. Grand cru wines are mostly single variety Riesling, Gewurztraminer, Pinot Gris or Muscat, and Vendanges Tardives or Sélection de Grains Nobles must show the vintage and one of five grape names.',
   'https://www.hachette-vins.com/tout-sur-le-vin/regions-vins/76/alsace/', 'published'),
  ('wr_0108', 'Beaujolais', '{"Vin du Beaujolais"}'::text[], 'FR', 46.055, 4.644, 17,
   'Beaujolais is Gamay country, making mostly light, fruity reds that range from early drinking Beaujolais Nouveau to the ten crus. A little white wine is made from Chardonnay.',
   2, null, 2, 'A versatile red that suits meat dishes and fish alike.', 'AOC Beaujolais may be followed by Villages or by the name of the commune the grapes come from, printed as large as the appellation name; primeur or nouveau is for red and rosé only and must show the vintage. The ten crus are labelled under their own names and may add Cru du Beaujolais.',
   'https://winefolly.com/deep-dive/beaujolais/', 'published'),
  ('wr_0109', 'Languedoc', '{}'::text[], 'FR', 43.419, 3.025, 49,
   'A broad Mediterranean region across Aude, Gard and Hérault making red, rosé and white wines, plus sparkling Limoux and sweet Muscats. Most reds blend Grenache, Syrah, Carignan and Mourvèdre.',
   4, null, null, 'Picpoul de Pinet whites suit oysters.', null,
   'https://www.hachette-vins.com/tout-sur-le-vin/regions-vins/98/languedoc/', 'published'),
  ('wr_0110', 'Roussillon', '{}'::text[], 'FR', 42.659, 2.752, 25,
   'The wine region of Pyrénées-Orientales, best known for vins doux naturels such as Banyuls, Maury and Rivesaltes. Its dry reds blend Grenache, Carignan, Syrah and Mourvèdre.',
   4, null, null, 'Red Banyuls suits chocolate desserts.', 'Red Côtes du Roussillon must come from at least two grapes, with Syrah and Mourvèdre together at least 25% of the grower''s plantings and Carignan no more than 50%.',
   'https://www.hachette-vins.com/tout-sur-le-vin/regions-vins/100/roussillon/', 'published'),
  ('wr_0111', 'Provence', '{}'::text[], 'FR', 43.407, 6.190, 46,
   'Rosé makes up close to 90% of Provence wine, mostly in a dry style and from Grenache, Cinsault and Syrah. Bandol stands apart for long-lived reds built on Mourvèdre.',
   null, null, null, 'Provence rosé suits charcuterie and cold starters.', 'Red Bandol comes from plantings of 50 to 95% Mourvèdre and is aged at least 18 months in cask or foudre. Côtes de Provence may add one of five terroir names: Sainte-Victoire, Fréjus, La Londe, Pierrefeu or Notre-Dame des Anges.',
   'https://www.hachette-vins.com/tout-sur-le-vin/regions-vins/102/provence/', 'published'),
  ('wr_0112', 'Jura', '{}'::text[], 'FR', 46.757, 5.591, 17,
   'The Jura is one of France''s smaller wine regions and makes mostly white wine from Chardonnay and Savagnin. Its best known style is vin jaune, Savagnin aged for more than six years in oak under a veil of yeast.',
   null, null, null, 'Vin jaune goes well with Comté cheese.', 'Vin jaune is made from Savagnin and aged in oak without topping up until 15 December of the sixth year after harvest, at least 60 months of it under a veil of yeast. Only vin jaune may be sold in the clavelin, a bottle of about 62 cl.',
   'https://www.guildsomm.com/public_content/features/articles/b/wink-lorch/posts/jura-wine-styles', 'published'),
  ('wr_0113', 'Cahors', '{"AOC Cahors","Vin de Cahors"}'::text[], 'FR', 44.460, 1.301, 15,
   'Cahors makes only red wine, on both banks of the Lot river, from Malbec, known locally as Côt, with some Merlot and Tannat. The wines are dark in colour and made to age.',
   null, null, null, null, 'AOC Cahors is reserved for still red wine, with Côt at least 70% of each estate''s plantings. Labels may add the broader unit Sud-Ouest, in letters no larger than the appellation name.',
   'https://info.agriculture.gouv.fr/gedei/site/bo-agri/document_administratif-302391de-0e09-4b5c-95d4-ddadcaf4ebeb/telechargement', 'published'),
  ('wr_0114', 'Savoie', '{}'::text[], 'FR', 46.085, 6.445, 16,
   'Savoie''s vineyards sit on the first slopes of the Alps, and about 70 percent of the wine is white, mostly dry. Jacquère is the most planted grape and Mondeuse is the local red.',
   null, null, null, null, 'Vin de Savoie may add one of 16 cru names, such as Apremont, Chignin-Bergeron or Arbin, each with its own grape rules, and a grape name only when the wine comes from that grape alone. Its white sparkling wine must carry the word Crémant before the appellation name.',
   'https://www.hachette-vins.com/tout-sur-le-vin/regions-vins/340/savoie-et-bugey/', 'published'),
  ('wr_0115', 'Bekaa Valley', '{"Beqaa Valley","Bekaa","Beqaa"}'::text[], 'LB', 33.833, 36.000, 30,
   'Lebanon''s main wine region, a high valley at around 1,000 metres where most of the country''s vines grow. Summers are long, sunny and dry, and reds are built on Bordeaux and Rhône grapes.',
   4, null, null, null, 'Lebanon has no legal appellation system, so Bekaa Valley on a label is a place name, not a protected appellation.',
   'https://www.decanter.com/wine-news/opinion/jefford-on-monday/red-wines-lebanon-bekaa-350774/', 'published'),
  ('wr_0116', 'Canelones', '{}'::text[], 'UY', -34.566, -55.979, 38,
   'Uruguay''s largest wine region, with about two thirds of the national vineyard, on gently rolling land next to Montevideo. The climate is mild, the soils fertile, and Tannat is the leading grape.',
   null, null, null, null, 'Canelones may appear on a label only if the grapes were grown there, and the wine needs an INAVI certificate of geographical indication.',
   'https://www.inavi.com.uy/regiones/', 'published'),
  ('wr_0117', 'Maldonado', '{}'::text[], 'UY', -34.465, -54.792, 40,
   'Uruguay''s emerging wine region on the Atlantic coast around Punta del Este. It is cooler, with poor, rocky soils on ancient granite; Tannat leads the reds and Albariño the whites.',
   null, null, null, null, 'Maldonado, or a smaller place such as Garzón, may appear on a label only if the grapes were grown there, and the wine needs an INAVI certificate of geographical indication.',
   'https://www.inavi.com.uy/regiones/', 'published');

insert into public.grapes
  (grape_code, name, aliases, colour, summary, tastes, aged_note,
   body, acidity, tannin, publication_status)
values
  ('gr_0051', 'Silvaner', '{"Grüner Silvaner","Sylvaner"}'::text[], 'white',
   'A white grape most at home in Franken, Germany. Fairly neutral in flavour, it shows its soil clearly, giving earthy, herbal wines with fresh acidity.',
   '{"Pear","Herbs","Earthy","Mineral"}'::text[], 'The best examples can develop in the cellar for several years.', 2, 4, null, 'published'),
  ('gr_0052', 'Dornfelder', '{}'::text[], 'red',
   'A German red crossing from 1955, first bred to deepen the colour of pale reds. Its dark wines are fruity, with a gentle floral lift.',
   '{"Blackberry","Sour cherry","Floral notes"}'::text[], 'Barrel ageing can add vanilla and spice to the fruit.', 4, 3, 3, 'published'),
  ('gr_0053', 'Scheurebe', '{"Sämling 88"}'::text[], 'white',
   'A German crossing of Riesling bred by Georg Scheu. Highly aromatic, with blackcurrant and grapefruit, it is made in styles from bone dry to lusciously sweet.',
   '{"Blackcurrant","Grapefruit","Tangerine","Lychee"}'::text[], null, null, 4, null, 'published'),
  ('gr_0054', 'Corvina', '{"Corvina Veronese"}'::text[], 'red',
   'The leading red grape of Valpolicella and Bardolino near Verona in the Veneto. Fresh, light reds with sour cherry and bitter almond, and the backbone of Amarone.',
   '{"Sour cherry","Bitter almond","Herbs","Violet"}'::text[], 'Its thick skins suit drying for Amarone, which turns it into a full bodied, tannic red.', 2, 4, 2, 'published'),
  ('gr_0055', 'Garganega', '{"Grecanico Dorato"}'::text[], 'white',
   'The main white grape of Soave in the Veneto and one of Italy''s oldest varieties. Dry, delicate whites with citrus, white flower and almond notes.',
   '{"Citrus","White flowers","Apricot","Almond"}'::text[], 'Good Soave can age for around a decade, gaining richer and more complex notes.', null, 4, null, 'published'),
  ('gr_0056', 'Glera', '{"Prosecco"}'::text[], 'white',
   'The grape behind Prosecco, grown in the Veneto and Friuli Venezia Giulia. It makes light, fresh sparkling wines with apple, pear and white flower notes.',
   '{"Green apple","Pear","White peach","White flowers"}'::text[], null, 1, 4, null, 'published'),
  ('gr_0057', 'Nerello Mascalese', '{}'::text[], 'red',
   'The main red grape of Etna in Sicily, grown on the volcano''s slopes. Pale, light bodied reds with cherry, herbs and a mineral edge, and noticeable tannin.',
   '{"Cherry","Dried herbs","Mineral","Spice"}'::text[], 'The best Etna reds from this grape can age for many years.', 2, null, 4, 'published'),
  ('gr_0058', 'Carricante', '{}'::text[], 'white',
   'The main white grape of Etna Bianco, grown high on the volcanic soils of Mount Etna in Sicily. Dry, mineral whites with citrus, green apple and high acidity.',
   '{"Citrus","Green apple","Saline"}'::text[], 'It has good ageing potential.', null, 4, null, 'published'),
  ('gr_0059', 'Aglianico', '{}'::text[], 'red',
   'A red grape of southern Italy, mainly Campania and Basilicata, behind Taurasi and Aglianico del Vulture. Full bodied, tannic and fresh, with black cherry and smoke.',
   '{"Black cherry","Plum","Smoke","Leather"}'::text[], 'Its high tannin and acidity make it a wine for long ageing.', 5, 4, 5, 'published'),
  ('gr_0060', 'Lagrein', '{}'::text[], 'red',
   'A native red of Alto Adige, at home on warm, low sites around Bolzano. Full bodied reds with black cherry, dark berry and violet notes and firm tannins.',
   '{"Black cherry","Dark berries","Violet","Cocoa"}'::text[], 'It has mid term ageing potential, with the best wines evolving over about ten years.', 4, null, 4, 'published'),
  ('gr_0061', 'Schiava', '{"Vernatsch"}'::text[], 'red',
   'A red grape of Alto Adige, called Vernatsch in German, at home around Lake Kaltern and Santa Maddalena. Pale, light reds with red berry and violet notes.',
   '{"Strawberry","Raspberry","Red cherry","Violet"}'::text[], 'Better examples, such as Santa Maddalena Classico, can improve over a few years in bottle.', 2, 4, 2, 'published'),
  ('gr_0062', 'Friulano', '{"Tocai Friulano","Sauvignonasse"}'::text[], 'white',
   'The flagship white of Friuli Venezia Giulia, formerly called Tocai Friulano. Dry whites with herbal and floral notes and a typical almond finish.',
   '{"Almond","Herbs","White flowers","Peach"}'::text[], null, null, null, null, 'published'),
  ('gr_0063', 'Ribolla Gialla', '{"Rebula"}'::text[], 'white',
   'An ancient white of Friuli Venezia Giulia, on the border with Slovenia where it is called Rebula. Light, crisp whites with lemon and white pepper notes.',
   '{"Lemon","Tangerine","White pepper"}'::text[], 'It is also made as orange wine, with long contact on the skins.', 2, 4, null, 'published'),
  ('gr_0064', 'Albariño', '{"Alvarinho"}'::text[], 'white',
   'White grape of Galicia''s Rías Baixas and Portugal''s Vinho Verde, where it is called Alvarinho. It makes aromatic, high acid whites, usually without oak.',
   '{"Citrus","Peach","Honeysuckle","Saline"}'::text[], 'Usually unoaked; a few producers use oak.', null, 4, null, 'published'),
  ('gr_0065', 'Palomino', '{"Palomino Fino","Listán Blanco"}'::text[], 'white',
   'White grape behind almost all sherry, grown on the chalky albariza soils of Jerez. Neutral and low in acidity itself, it is the base of fino, manzanilla, amontillado and oloroso.',
   '{"Almond","Saline","Fresh dough"}'::text[], 'As fino it ages under a veil of flor yeast that protects it from air.', 2, 2, null, 'published'),
  ('gr_0066', 'Pedro Ximénez', '{"PX"}'::text[], 'white',
   'Andalusian white grape, dried in the sun after picking to make very sweet wines, mainly in Montilla-Moriles and Jerez.',
   '{"Fig","Raisin","Date","Coffee"}'::text[], 'Aged oxidatively, in contact with air.', 5, null, null, 'published'),
  ('gr_0067', 'Verdejo', '{}'::text[], 'white',
   'White grape grown mostly in Rueda, making crisp, herbal whites, often with a light bitter almond finish.',
   '{"Fennel","Citrus","White peach","Bitter almond"}'::text[], 'Lees ageing and barrel fermentation give richer versions.', null, 4, null, 'published'),
  ('gr_0068', 'Mencía', '{"Jaen"}'::text[], 'red',
   'Red grape of north west Spain, mainly Bierzo, Ribeira Sacra and Valdeorras, called Jaen in Portugal. It makes fragrant, medium-bodied reds.',
   '{"Sour cherry","Floral","Pepper","Herbs"}'::text[], 'Oak adds smoky spice and softens the tannins.', 3, 4, 3, 'published'),
  ('gr_0069', 'Carignan', '{"Cariñena","Carinyena","Samsó","Mazuelo","Mazuela","Carignano"}'::text[], 'red',
   'Red grape of Spanish origin, grown widely in southern France, Catalonia and Sardinia and often blended with Grenache and Syrah. In Spain it is Cariñena, Mazuelo or Samsó.',
   '{"Red fruit","Baking spice","Herbs"}'::text[], 'Takes well to oak, which adds spice.', null, 4, 4, 'published'),
  ('gr_0070', 'Xarel·lo', '{"Xarel-lo","Pansa Blanca"}'::text[], 'white',
   'Catalan white grape, mainly from Penedès. One of the three main Cava grapes, it is also made as a still wine.',
   '{"Citrus","Peach","Herbs"}'::text[], 'Ages well and adds longevity to sparkling blends.', null, 4, null, 'published'),
  ('gr_0071', 'Macabeo', '{"Viura","Macabeu"}'::text[], 'white',
   'Spanish white grape, the main white of Rioja as Viura and a main Cava grape. It makes light, floral whites that can age well.',
   '{"Citrus","Floral","Hazelnut","Almond paste"}'::text[], 'Can age for years; barrel aged versions gain structure.', 2, 3, null, 'published'),
  ('gr_0072', 'Loureiro', '{}'::text[], 'white',
   'A fragrant white grape of Portugal''s Vinho Verde, often bottled on its own, giving bright wines with blossom and peach aromas.',
   '{"Peach","Lime blossom","Bay leaf"}'::text[], 'Mostly drunk young, though single-variety wines can age a few years.', null, 5, null, 'published'),
  ('gr_0073', 'Baga', '{}'::text[], 'red',
   'The signature red of Bairrada, a small, thick-skinned grape giving deeply coloured, high-acid, tannic reds that can be tough young and soften with age.',
   '{"Cherry","Plum","Tobacco","Coffee"}'::text[], 'Often astringent young, it softens and gains complexity over many years.', null, 5, 5, 'published'),
  ('gr_0074', 'Encruzado', '{}'::text[], 'white',
   'A rare white grape grown almost only in Portugal''s Dão, used alone and in blends, giving wines with citrus, resin and mineral notes.',
   '{"Citrus","Resin","Mineral"}'::text[], 'Takes well to oak and can age for years.', null, null, null, 'published'),
  ('gr_0075', 'Alicante Bouschet', '{}'::text[], 'red',
   'A French crossing with red flesh as well as red skin, now a mainstay of Portugal''s Alentejo, giving dark, full, tannic reds.',
   '{"Blackberry","Tobacco"}'::text[], 'Can age well, gaining savoury notes with time.', 5, null, 4, 'published'),
  ('gr_0076', 'Trincadeira', '{"Tinta Amarela","Trincadeira Preta"}'::text[], 'red',
   'One of Portugal''s most widely planted reds, called Tinta Amarela in the Douro, making dry reds with herbal and floral notes.',
   '{"Herbs","Flowers"}'::text[], null, null, null, null, 'published'),
  ('gr_0077', 'Antão Vaz', '{}'::text[], 'white',
   'The leading white grape of Portugal''s Alentejo, giving firm, full-bodied whites with ripe tropical fruit, tangerine peel and a mineral note.',
   '{"Tropical fruit","Tangerine peel","Mineral"}'::text[], 'Riper, later-picked fruit suits ageing in oak barrels.', 4, null, null, 'published'),
  ('gr_0078', 'Touriga Franca', '{}'::text[], 'red',
   'A main grape of the Douro, used in Port and in dry reds and often blended, giving wines with blackberry and floral notes.',
   '{"Blackberry","Rose"}'::text[], 'Adds ageing potential to blends and can age a decade or more.', null, null, null, 'published'),
  ('gr_0079', 'Sercial', '{"Esgana Cão"}'::text[], 'white',
   'A late-ripening white grape, known as Esgana Cão on the mainland, that makes the driest style of Madeira, with very high acidity.',
   '{"Lemon peel","Nuts","Herbs","Saline"}'::text[], 'Needs long cask ageing to soften its acidity, then lasts for decades.', null, 5, null, 'published'),
  ('gr_0080', 'Verdelho', '{}'::text[], 'white',
   'A white grape best known on Madeira for a medium-dry style, richer than Sercial but still high in acid; in Australia it makes dry, aromatic whites.',
   '{"Caramel","Nuts","Spice"}'::text[], 'As Madeira it can age for many decades.', null, 4, null, 'published'),
  ('gr_0081', 'Tinta Negra', '{"Tinta Negra Mole"}'::text[], 'red',
   'A red grape and Madeira''s most planted variety, the source of most Madeira and the only one used across every style from dry to rich.',
   '{}'::text[], null, null, null, null, 'published'),
  ('gr_0082', 'Muscat of Alexandria', '{"Moscatel de Setúbal","Moscatel Graúdo","Moscatel de Alejandría","Zibibbo"}'::text[], 'white',
   'Known in Portugal as Moscatel de Setúbal, this Muscat gives aromatic, floral wines, most famously the sweet fortified wines of Setúbal.',
   '{"Lychee","Orange","Honey","Flowers"}'::text[], null, null, null, null, 'published'),
  ('gr_0083', 'Savagnin', '{"Savagnin Blanc","Naturé"}'::text[], 'white',
   'The Jura white grape behind vin jaune. High in acidity, with citrus and apple notes, and a close relative of Gewürztraminer.',
   '{"Citrus","Apple","Almond","Walnut"}'::text[], 'Aged under a veil of yeast as vin jaune, it takes on walnut, hazelnut and spice notes.', null, 4, null, 'published'),
  ('gr_0084', 'Poulsard', '{"Ploussard"}'::text[], 'red',
   'A Jura red that makes very pale, light wines with little tannin, so pale they are sometimes taken for rosé, with red berry fruit.',
   '{"Red berries"}'::text[], null, 2, null, 1, 'published'),
  ('gr_0085', 'Trousseau', '{"Bastardo","Merenzao"}'::text[], 'red',
   'A Jura red with more colour and tannin than Poulsard, showing strawberry and cherry fruit with pepper and spice. A relative of Savagnin.',
   '{"Strawberry","Cherry","Pepper","Forest floor"}'::text[], 'It develops more intense, complex aromas over a few years in bottle.', null, null, null, 'published'),
  ('gr_0086', 'Jacquère', '{}'::text[], 'white',
   'The most planted white grape of Savoie, giving fresh, light wines with white flowers, pear and citrus, made for early drinking.',
   '{"White flowers","Pear","Citrus"}'::text[], 'Made to be drunk young, within a few years of the vintage.', 2, null, null, 'published'),
  ('gr_0087', 'Mondeuse', '{"Mondeuse Noire"}'::text[], 'red',
   'A Savoie red with deep colour, firm structure and strawberry, raspberry and spice notes. It rewards a few years of cellaring.',
   '{"Strawberry","Raspberry","Spice"}'::text[], 'Often best after two years or more in bottle, and good examples keep for many years.', null, null, null, 'published'),
  ('gr_0088', 'Altesse', '{"Roussette"}'::text[], 'white',
   'A Savoie white grape, also called Roussette, giving fuller wines than Jacquère, with almond, honey, pineapple and bergamot notes.',
   '{"Almond","Honey","Pineapple","Bergamot"}'::text[], 'It improves with a few years in bottle.', null, null, null, 'published'),
  ('gr_0089', 'Vermentino', '{"Rolle","Vermentinu"}'::text[], 'white',
   'A white grape grown around the Mediterranean and known in southern France as Rolle. It gives light, fresh wines with notes of grapefruit, apple and almond.',
   '{"Grapefruit","Apple","Almond"}'::text[], null, 2, null, null, 'published'),
  ('gr_0090', 'Tannat', '{"Harriague"}'::text[], 'red',
   'A red grape with thick skins from southwest France, best known from Madiran and also widely grown in Uruguay. It makes robust wines with firm tannins.',
   '{"Plum","Smoke"}'::text[], 'It benefits from bottle age, and good examples can be kept for ten years or more.', 5, null, 5, 'published'),
  ('gr_0091', 'Grenache Blanc', '{"Garnacha Blanca"}'::text[], 'white',
   'The white form of Grenache, from Spain and also grown in southern France. Its wines are round and low in acidity, and it is often used in blends.',
   '{"Plum"}'::text[], null, null, 2, null, 'published');

update public.grapes g set similar_grape_id = s.id, similar_note = 'Its parent, which it echoes from dry to sweet, with riper, more exotic fruit.' from public.grapes s where s.grape_code = 'gr_0008' and g.grape_code = 'gr_0053';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Fresh Valpolicella is often likened to Beaujolais.' from public.grapes s where s.grape_code = 'gr_0014' and g.grape_code = 'gr_0054';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Pale, light bodied and fragrant reds that are often likened to it.' from public.grapes s where s.grape_code = 'gr_0001' and g.grape_code = 'gr_0057';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Often called the Barolo of the south for its structure and depth.' from public.grapes s where s.grape_code = 'gr_0009' and g.grape_code = 'gr_0059';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Dry Riesling is a common comparison.' from public.grapes s where s.grape_code = 'gr_0008' and g.grape_code = 'gr_0064';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Its usual blending partner in Rueda.' from public.grapes s where s.grape_code = 'gr_0011' and g.grape_code = 'gr_0067';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Often suggested to Pinot Noir drinkers; Mencía is more peppery and savoury.' from public.grapes s where s.grape_code = 'gr_0001' and g.grape_code = 'gr_0068';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Lighter Carignan is often compared with Zinfandel.' from public.grapes s where s.grape_code = 'gr_0028' and g.grape_code = 'gr_0069';
update public.grapes g set similar_grape_id = s.id, similar_note = 'A relative of Syrah that shares some of its spice.' from public.grapes s where s.grape_code = 'gr_0005' and g.grape_code = 'gr_0087';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Grenache Blanc is a colour mutation of the same grape.' from public.grapes s where s.grape_code = 'gr_0006' and g.grape_code = 'gr_0091';
update public.grapes set aliases = aliases || '{"Carignan Noir"}'::text[] where grape_code = 'gr_0069';

