  ('wa_0301', 'Monção e Melgaço', '{}'::text[], 'wr_0102', 'mixed', 'Along the south bank of the Minho, with cold winters and hot, dry summers. The home of Alvarinho, with Pedral for reds.', 1),
  ('wa_0302', 'Lima', '{}'::text[], 'wr_0102', 'mixed', 'The wettest sub-region. Whites are led by Loureiro; reds come mainly from Vinhão and Borraçal.', 2),
  ('wa_0303', 'Cávado', '{}'::text[], 'wr_0102', 'mixed', 'A mild, low river basin open to sea winds. Whites from Arinto, Loureiro and Trajadura; reds mostly Vinhão and Borraçal.', 3),
  ('wa_0304', 'Ave', '{}'::text[], 'wr_0102', 'white', 'Low ground across the Ave basin, exposed to sea winds. Mainly fresh whites with floral and citrus notes.', 4),
  ('wa_0305', 'Basto', '{}'::text[], 'wr_0102', 'mixed', 'The most inland sub-region, with cold, very wet winters and hot summers that suit late ripening Azal, Espadeiro and Rabo-de-Anho.', 5),
  ('wa_0306', 'Sousa', '{}'::text[], 'wr_0102', 'mixed', 'A mild transition zone. Arinto, Loureiro and Trajadura with Azal and Avesso; Espadeiro is much used for rosé.', 6),
  ('wa_0307', 'Amarante', '{}'::text[], 'wr_0102', 'mixed', 'Inland and higher, with warmer summers. Suits Azal, Avesso, Amaral and Espadeiro, and Vinhão ripens well for reds.', 7),
  ('wa_0308', 'Paiva', '{}'::text[], 'wr_0102', 'mixed', 'Inland and higher, where Amaral and above all Vinhão ripen fully; Avesso joins the usual whites.', 8),
  ('wa_0309', 'Baião', '{}'::text[], 'wr_0102', 'mixed', 'The south eastern edge, with colder winters and drier summers that ripen late grapes such as Azal, Avesso and Amaral.', 9),
